from lib import *
S = SS('f40')
R = J('f40'); c = R['cost']
steps = [
    step("jsonify 的输出(实测):Content-Type 是 application/json;键默认排序(jsonify(b=2, a=1, 中文='值') 得到 {\"a\":1,\"b\":2,\"\\u4e2d\\u6587\":\"\\u503c\"});默认 ensure_ascii = True,中文被转成 \\uXXXX 转义;非 debug 时是紧凑格式(没有空格)、末尾有换行。jsonify([1,2,{...}]) 返回数组;jsonify(1,2,3) 多个位置参数变成数组 [1,2,3];jsonify() 无参数是 null。provider 是 DefaultJSONProvider(sort_keys = True、ensure_ascii = True、compact = None、mimetype = application/json)。", t=tl(S(1)), done=lidx(S(1), 'GET /j ', 'GET /list', 'GET /one'), mark=lidx(S(1), 'GET /many', 'GET /none', 'app.json 类型'), kv=KV([['sort_keys', 'True(默认排序键)'], ['ensure_ascii', 'True(中文变 \\uXXXX)'], ['compact', 'None → 由 debug 决定']], ['ensure_ascii'])),
    step("compact 为 None 时由 debug 决定:app.debug = True 时输出缩进的 JSON(两个空格缩进,每个键一行)。同一个接口在调试环境与生产环境的字节内容不同。", t=tl(S(2)), done=lidx(S(2), 'app.debug=True'), kv=KV([['debug=False', '紧凑'], ['debug=True', '缩进两空格']], ['debug=True'])),
    step("各类型的序列化(实测):datetime、date 变成 RFC 822 的 HTTP 日期字符串(\"Fri, 02 Oct 2026 12:30:45 GMT\"),无时区的 naive datetime 也被当成 GMT;UUID → 字符串;Decimal → 字符串 \"1.10\";dataclass → 对象;带 __html__ 的对象 → 它的 HTML 字符串;tuple → 数组;键是 int → 转成字符串键。不能序列化:time、Enum、set、bytes、complex、普通对象 → TypeError「Object of type … is not JSON serializable」;tuple 作键 → TypeError。NaN 与 Infinity 会原样输出(NaN、Infinity),这不是合法的 JSON。", t=tl(S(3)), done=lidx(S(3), 'datetime    ', 'UUID', 'Decimal', 'dataclass'), mark=lidx(S(3), 'time ', 'Enum', 'set', 'float nan', 'float inf'), kv=KV([['datetime / date', 'HTTP 日期字符串,naive 当 GMT'], ['Decimal / UUID', '字符串'], ['set / bytes / Enum / 普通对象', 'TypeError'], ['NaN / inf', '原样输出,非法 JSON']], ['NaN / inf'])),
    step("自定义序列化:子类化 DefaultJSONProvider,设 sort_keys = False,重写 default 处理 set(排序成列表)、bytes(按 latin-1 解成字符串)、有 __dict__ 的对象(vars());jsonify(z=1, a={3,1,2}, raw=b'ab', obj=Plain()) 的输出是 {\"z\":1,\"a\":[1,2,3],\"raw\":\"ab\",\"obj\":{\"a\":1}} —— 键保持插入顺序。用 app.json = MyProvider(app) 安装。", t=tl(S(4)), done=lidx(S(4), '自定义 provider'), kv=KV([['sort_keys=False', '保持插入顺序'], ['default()', '处理 set / bytes / 对象']], ['default()'])),
    step("视图直接 return dict 与 return jsonify(dict) 的响应完全相同(正文与 Content-Type 一致):dict 与 list 的返回值内部就是调用 app.json.response()。", t=tl(S(5)), done=lidx(S(5), 'return dict'), kv=KV([['return dict', '=== jsonify(dict)']], ['return dict'])),
    step(f"耗时:1000 个对象(每个 5 个字段,输出约 73540 字节)app.json.dumps 默认(sort_keys=True){c[0]:.3f} ms;sort_keys=False {c[1]:.3f} ms;标准库 json.dumps {c[2]:.3f} ms;标准库紧凑分隔符 {c[3]:.3f} ms。排序键多花约 {c[0] - c[1]:.2f} ms(约 {(c[0] / c[1] - 1) * 100:.0f}%),不排序时与标准库相当。", t=tl(S(6)), b=bars([['dumps sort_keys=True', c[0], f'{c[0]:.3f} ms'], ['dumps sort_keys=False', c[1], f'{c[1]:.3f} ms'], ['标准库 json.dumps', c[2], f'{c[2]:.3f} ms']], c[0], done=[0, 1, 2]), kv=KV([['sort_keys=True(默认)', f'{c[0]:.3f} ms'], ['sort_keys=False', f'{c[1]:.3f} ms'], ['标准库', f'{c[2]:.3f} ms']], ['sort_keys=True(默认)'])),
]
